\definecolor{coolblue}{HTML}{2980B9}       % Cool blue (solutions)
\definecolor{tealgreen}{HTML}{1ABC9C}      % Teal (adaptation)
\definecolor{bgposter}{HTML}{0A1628}       % Very dark navy background
\definecolor{cardbg1}{HTML}{0F2338}        % Dark card bg variant 1
\definecolor{cardbg2}{HTML}{132B45}        % Dark card bg variant 2
\definecolor{cardbg3}{HTML}{0D1F35}        % Dark card bg variant 3
\definecolor{statbg}{HTML}{0E1E34}         % Stat banner bg
\definecolor{stathighlight}{HTML}{1A0808}  % Stat callout highlight
\definecolor{textwhite}{HTML}{ECF0F1}       % Primary text
\definecolor{textlight}{HTML}{BDC3C7}       % Secondary text
\definecolor{textdim}{HTML}{7F8C8D}         % Tertiary text
\definecolor{divider}{HTML}{1B3A5C}         % Divider lines

\pagecolor{bgposter}
\color{textwhite}

% ══════════════════════════════════════════════════
%  List Styling
% ══════════════════════════════════════════════════
\setlist[itemize]{leftmargin=28pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{accentamber}\bfseries\arabic*.}}

% ══════════════════════════════════════════════════
%  Card Styles (Left Accent Stripe — Dark Theme)
% ══════════════════════════════════════════════════
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg1,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
