% ══════════════════════════════════════════════════
%  Helper Macros
% ══════════════════════════════════════════════════
\newcommand{\bodytext}{\fontsize{32}{42}\selectfont\color{textwhite}}
\newcommand{\dimtext}{\fontsize{28}{36}\selectfont\color{textlight}}
\newcommand{\statnum}[1]{{\fontsize{64}{76}\selectfont\bfseries\color{accent}#1}}
\newcommand{\statnumamber}[1]{{\fontsize{64}{76}\selectfont\bfseries\color{accentamber}#1}}
\newcommand{\statnumblue}[1]{{\fontsize{64}{76}\selectfont\bfseries\color{coolblue}#1}}
\newcommand{\statlabel}[1]{{\fontsize{26}{32}\selectfont\color{textlight}#1}}

\newcommand{\infobox}[2]{%
  \colorbox{cardbg2}{\parbox{0.92\linewidth}{%
    \vspace{6pt}\fontsize{30}{38}\selectfont\color{accentamber}\textbf{#1}\par\vspace{2pt}%
    \fontsize{28}{36}\selectfont\color{textlight}#2\vspace{6pt}%
  }}\vspace{4pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════
%  TITLE BAR (span=3, rows 0–3)
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries\color{textwhite}%
    Climate Change 2023}\\[10pt]
  {\fontsize{52}{62}\selectfont\bfseries\color{accentamber}%
    Key Findings from the IPCC Sixth Assessment Synthesis Report}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{textlight}%
    Intergovernmental Panel on Climate Change\enspace$\bullet$\enspace
