  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={3pt}{0pt}{accent!50},
]{name=stats, column=1, span=3, between=row3 and row6}{
  % ── Top row: 3 metrics ──
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      \statnum{1.1\textdegree C}\\[4pt]
      \statlabel{Global surface temp.\ rise\\(2011--2020 vs.\ 1850--1900)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accentamber!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      \statnumamber{410 ppm}\\[4pt]
      \statlabel{Atmospheric CO$_2$ in 2019\\(highest in 2M years)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
