389	  \begin{itemize}[itemsep=12pt, label={\color{accent}$\blacktriangleright$}]
390	    \item \textbf{Delayed action} $\Rightarrow$ higher costs, locked-in carbon infrastructure
391	    \item \textbf{Each fraction of a degree} matters --- risks escalate non-linearly
392	    \item Climate finance \textbf{3--6$\times$ insufficient} for adaptation alone
393	    \item Feasibility of 1.5\textdegree C diminishes with every year of inaction
394	  \end{itemize}
395	  \vspace{8pt}
396	  \colorbox{accent!35}{\parbox{0.92\linewidth}{%
397	    \vspace{8pt}\centering
398	    {\fontsize{30}{38}\selectfont\bfseries\color{textwhite}Immediate, deep, and sustained emissions reductions across all sectors are essential}\vspace{8pt}%
399	  }}
400	}
