     \\centering\\vspace{8pt}%\n      \\statnumamber{59 GtCO$_2$e}\\\\[4pt]\n      \\statlabel{Global GHG emissions\\\\in 2019}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\\\[12pt]\n  % ── Bottom row: 4 metrics (2 key ones emphasized) ──\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{coolblue!40}{stathighlight}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      \\statnumblue{$\\sim$500}\\\\[2pt]\n      \\fontsize{36}{44}\\selectfont\\bfseries\\color{coolblue}GtCO$_2$\\\\[4pt]\n      \\statlabel{Carbon budget for\\\\1.5\\textdegree C (50\\%)}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.24\\linewidth}\\centering\n    \\fcolorbox{accent!60}{accent!25!bgposter}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      {\\fontsize{72}{86}\\selectfont\\bfseries\\color{accent}43\\%}\\\\[4pt]\n      \\statlabel{GHG reduction needed\\\\by 2030 for 1.5\\textdegree C}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{accentamber!40}{stathighlight}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      \\statnumamber{$\\sim$0.20 m}\\\\[4pt]\n      \\statlabel{Sea level rise\\\\(1901--2018)}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.24\\linewidth}\\centering\n    \\fcolorbox{accent!60}{accent!25!bgposter}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      {\\fontsize{60}{72}\\selectfont\\bfseries\\color{accent}3.3--3.6B}\\\\[4pt]\n      \\statlabel{People exposed to\\\\severe climate hazards}\\vspace{6pt}%\n    }}\n  \\end{minipage}\n}\n\n% ══════════════════════════════════════════════════\n%  OBSERVED CHANGES (Col 1, rows 6–11)\n% ══════════════════════════════════════════════════\n\\posterbox[redcard, title={Observed Changes}\n]{name=observed, column=1, between=row6 and row11}{\n  \\bodytext\n  \\begin{itemize}[itemsep=14pt]\n    \\item \\textbf{+1.1\\textdegree C} warming since pre-industrial era\n    \\item CO$_2$ at \\textbf{410 ppm} --- highest in 2 million years\n    \\item GHG emissions \\textbf{59 GtCO$_2$e} in 2019\n    \\item Arctic sea ice: \\textbf{$\\sim$40\\%} area loss (1979--2020)\n    \\item Sea level rose $\\sim$0.20\\,m since 1901\n  \\end{itemize}\n  \\vspace{6pt}\n  \\colorbox{accent!20}{\\parbox{0.92\\linewidth}{%\n    \\vspace{6pt}\\fontsize{28}{36}\\selectfont\\color{accent}\\textbf{Every region} affected by intensifying extreme weather: heatwaves, heavy precipitation, droughts, cyclones\\vspace{6pt}%\n  }}\n}\n\n% ══════════════════════════════════════════════════\n%  FUTURE PROJECTIONS — SSP TABLE (Col 2, rows 6–9)\n% ══════════════════════════════════════════════════\n\\posterbox[ambercard, title={Future Projections: SSP Scenarios}\n]{name=ssptable, column=2, between=row6 and row10}{\n  \\fontsize{28}{36}\\selectfont\\color{textwhite}\n  \\renewcommand{\\arraystretch}{1.8}\n  \\begin{tabular}{>{\\bfseries\\color{textwhite}}l >{\\color{accentamber}}c p{130mm}}\n    \\rowcolor{cardbg2}\n    \\fontsize{26}{32}\\selectfont\\color{accentamber}\\textbf{Scenario} &\n    \\fontsize{26}{32}\\selectfont\\color{accentamber}\\textbf{2100} &\n    \\fontsize{26}{32}\\selectfont\\color{accentamber}\\textbf{Pathway} \\\\\n    \\rowcolor{cardbg1}\n    SSP1-1.9 & $\\sim$1.4\\textdegree C & Very low emissions \\\\\n    \\rowcolor{cardbg2}\n    SSP1-2.6 & $\\sim$1.8\\textdegree C & Low emissions \\\\\n    \\rowcolor{cardbg1}\n    SSP2-4.5 & $\\sim$2.7\\textdegree C & Intermediate \\\\\n    \\rowcolor{cardbg2}\n    SSP3-7.0 & $\\sim$3.6\\textdegree C & High emissions \\\\\n    \\rowcolor{cardbg1}\n    SSP5-8.5 & $\\sim$4.4\\textdegree C & Very high emissions \\\\\n  \\end{tabular}\n  \\vspace{4pt}\n  \\dimtext Sea level: \\textbf{0.28--0.55\\,m} (SSP1-1.9) to \\textbf{0.63--1.01\\,m} (SSP5-8.5) by 2100; rise continues for centuries\n}\n\n% ══════════════════════════════════════════════════\n%  SSP PATHWAY DIAGRAM (Col 2, rows 10–11)\n% ══════════════════════════════════════════════════\n\\posterbox[darkcard, title={Warming Pathways}\n]{name=sspdiagram, column=2, between=row10 and row11}{\n  \\centering\n  \\begin{tikzpicture}[x=1.2mm, y=26mm]\n    % Axes\n    \\draw[thick, textlight] (0,1.0) -- (0,4.6);\n    \\draw[thick, textlight] (0,1.0) -- (82,1.0);\n    % Y-axis labels\n    \\foreach \\y in {1.5,2.0,2.5,3.0,3.5,4.0,4.5} {\n      \\draw[textdim, thin] (0,\\y) -- (80,\\y);\n      \\node[left, font=\\fontsize{18}{22}\\selectfont, textdim] at (0,\\y) {\\y\\textdegree C};\n    }\n    % X-axis labels\n    \\foreach \\x/\\yr in {0/2020,20/2040,40/2060,60/2080,80/2100} {\n      \\node[below, font=\\fontsize{18}{22}\\selectfont, textdim] at (\\x,1.0) {\\yr};\n    }\n    % 1.5 and 2.0 thresholds\n    \\draw[dashed, very thick, tealgreen] (0,1.5) -- (80,1.5);\n    \\node[right, font=\\fontsize{18}{22}\\selectfont, tealgreen] at (80.5,1.5) {1.5\\textdegree C};\n    \\draw[dashed, very thick, accentamber] (0,2.0) -- (80,2.0);\n    \\node[right, font=\\fontsize{18}{22}\\selectfont, accentamber] at (80.5,2.0) {2.0\\textdegree C};\n    % SSP Pathways (Bézier curves from 2020 at ~1.1°C)\n    \\draw[very thick, tealgreen] (0,1.1) .. controls (15,1.2) and (40,1.3) .. (80,1.4);\n    \\node[right, font=\\fontsize{16}{20}\\selectfont, tealgreen] at (81,1.4) {1.9};\n    \\draw[very thick, coolblue] (0,1.1) .. controls (15,1.25) and (40,1.5) .. (80,1.8);\n    \\node[right, font=\\fontsize{16}{20}\\selectfont, coolblue] at (81,1.8) {2.6};\n    \\draw[very thick, accentamber] (0,1.1) .. controls (15,1.4) and (40,2.0) .. (80,2.7);\n    \\node[right, font=\\fontsize{16}{20}\\selectfont, accentamber] at (81,2.7) {4.5};\n    \\draw[very thick, orange] (0,1.1) .. controls (15,1.5) and (40,2.5) .. (80,3.6);\n    \\node[right, font=\\fontsize{16}{20}\\selectfont, orange] at (81,3.6) {7.0};\n    \\draw[very thick, accent] (0,1.1) .. controls (15,1.6) and (40,3.0) .. (80,4.4);\n    \\node[right, font=\\fontsize{16}{20}\\selectfont, accent] at (81,4.4) {8.5};\n  \\end{tikzpicture}\n}\n\n% ══════════════════════════════════════════════════\n%  RISKS & VULNERABILITIES (Col 3, rows 6–11)\n% ══════════════════════════════════════════════════\n\\posterbox[redcard, title={Risks \\& Vulnerabilities}\n]{name=risks, column=3, between=row6 and row11}{\n  \\bodytext\n  \\colorbox{accent!25}{\\parbox{0.92\\linewidth}{%\n    \\vspace{6pt}\\centering\n    {\\fontsize{54}{64}\\selectfont\\bfseries\\color{accent}3.3--3.6 Billion}\\\\[4pt]\n    {\\fontsize{26}{32}\\selectfont\\color{textlight}people highly vulnerable to climate change}\\vspace{6pt}%\n  }}\n  \\vspace{8pt}\n  \\begin{itemize}[itemsep=12pt]\n    \\item Cascading \\& compounding risks interact with poverty, inequality\n    \\item Up to \\textbf{14\\%} terrestrial species at very high extinction risk at 1.5\\textdegree C+\n  \\end{itemize}\n  \\vspace{6pt}\n  \\infobox{Food Security}{Crop yield growth slowing; tropical fisheries declining}\n  \\infobox{Water Stress}{Half the world: severe water scarcity $\\geq$1 month/year}\n  \\infobox{Health}{Heat mortality rising; vector-borne disease ranges expanding}\n}\n\n% ══════════════════════════════════════════════════\n%  MITIGATION PATHWAYS (Col 1, rows 11–16)\n% ══════════════════════════════════════════════════\n\\posterbox[ambercard, title={Mitigation Pathways}\n]{name=mitigation, column=1, between=row11 and row16}{\n  \\bodytext\n  \\colorbox{accent!25}{\\parbox{0.92\\linewidth}{%\n    \\vspace{6pt}\\centering\n    {\\fontsize{54}{64}\\selectfont\\bfseries\\color{accent}43\\%}\\\\[4pt]\n    {\\fontsize{26}{32}\\selectfont\\color{textlight}GHG reduction below 2019 levels by 2030}\\\\[2pt]\n    {\\fontsize{24}{30}\\selectfont\\color{textdim}for 1.5\\textdegree C with no/limited overshoot}\\vspace{6pt}%\n  }}\n  \\vspace{8pt}\n  \\begin{itemize}[itemsep=10pt]\n    \\item Net zero CO$_2$ by \\textbf{$\\sim$2050} for 1.5\\textdegree C\n    \\item Net zero CO$_2$ by \\textbf{$\\sim$2070} for 2\\textdegree C\n    \\item 27\\% reduction by 2030 for 2\\textdegree C target\n  \\end{itemize}\n  \\vspace{6pt}\n  \\colorbox{coolblue!20}{\\parbox{0.92\\linewidth}{%\n    \\vspace{6pt}\\fontsize{28}{36}\\selectfont\\color{coolblue}\\textbf{Remaining carbon budget (1.5\\textdegree C, 50\\%):} $\\sim$500 GtCO$_2$ from 2020\\vspace{6pt}%\n  }}\n}\n\n% ══════════════════════════════════════════════════\n%  KEY MITIGATION LEVERS (Col 2, rows 11–16)\n% ══════════════════════════════════════════════════\n\\posterbox[tealcard, title={Mitigation Levers \\& Adaptation}\n]{name=levers, column=2, between=row11 and row16}{\n  \\bodytext\n  \\textbf{\\color{tealgreen}Key Mitigation Levers}\n  \\begin{enumerate}[itemsep=10pt]\n    \\item Rapid decarbonization of energy systems\n    \\item Electrification of transport\n    \\item Demand-side efficiency improvements\n    \\item Protection \\& restoration of carbon sinks\n  \\end{enumerate}\n  \\vspace{8pt}\n  \\textbf{\\color{coolblue}Adaptation Strategies}\n  \\begin{itemize}[itemsep=8pt, label={\\color{coolblue}$\\blacktriangleright$}]\n    \\item Climate-resilient infrastructure\n    \\item Ecosystem-based adaptation\n    \\item Early warning systems\n    \\item Integrated water management\n  \\end{itemize}\n  \\vspace{6pt}\n  \\colorbox{accentamber!20}{\\parbox{0.92\\linewidth}{%\n    \\vspace{6pt}\\fontsize{26}{32}\\selectfont\\color{accentamber}\\textbf{Finance gap:} adaptation funding falls short by factor of \\textbf{3--6}$\\times$\\vspace{6pt}%\n  }}\n}\n\n% ══════════════════════════════════════════════════\n%  NARROWING WINDOW (Col 3, rows 11–16)\n% ══════════════════════════════════════════════════\n\\posterbox[highlightcard, title={The Narrowing Window}\n]{name=window, column=3, between=row11 and row16}{\n  \\bodytext\n  \\colorbox{accent!30}{\\parbox{0.92\\linewidth}{%\n    \\vspace{8pt}\\fontsize{30}{38}\\selectfont\\color{textwhite}\\textbf{Choices made this decade determine whether warming can be held to 1.5\\textdegree C or 2\\textdegree C}\\vspace{8pt}%\n  }}\n  \\vspace{10pt}\n  \\begin{itemize}[itemsep=12pt, label={\\color{accent}$\\blacktriangleright$}]\n    \\item \\textbf{Delayed action} $\\Rightarrow$ higher costs, locked-in carbon infrastructure\n    \\item \\textbf{Each fraction of a degree} matters --- risks escalate non-linearly\n    \\item Climate finance \\textbf{3--6$\\times$ insufficient} for adaptation alone\n    \\item Feasibility of 1.5\\textdegree C diminishes with every year of inaction\n  \\end{itemize}\n  \\vspace{8pt}\n  \\colorbox{accent!35}{\\parbox{0.92\\linewidth}{%\n    \\vspace{8pt}\\centering\n    {\\fontsize{30}{38}\\selectfont\\bfseries\\color{textwhite}Immediate, deep, and sustained emissions reductions across all sectors are essential}\\vspace{8pt}%\n  }}\n}\n\n% ══════════════════════════════════════════════════\n%  CALL TO ACTION (span=3, rows 16–20)\n% ══════════════════════════════════════════════════\n\\posterbox[\n  enhanced, colback=primary, colframe=primary, colupper=textwhite,\n  arc=0pt, boxrule=0pt,\n  left=40pt, right=40pt, top=14pt, bottom=14pt,\n  valign=center,\n]{name=calltoaction, column=1, span=3, between=row16 and row20}{\n  \\centering\n  {\\fontsize{48}{58}\\selectfont\\bfseries\\color{accent}%\n    Securing a Liveable and Sustainable Future for All}\\\\[16pt]\n  {\\fontsize{34}{44}\\selectfont\\color{textlight}%\n    The scientific evidence is unequivocal: climate change is a threat to human well-being and planetary health.}\\\\[8pt]\n  {\\fontsize{34}{44}\\selectfont\\color{textlight}%\n    There is a rapidly narrowing window of opportunity to enable climate-resilient development.}\\\\[14pt]\n  \\begin{minipage}[c]{0.30\\linewidth}\\centering\n    \\fcolorbox{accent!50}{accent!20}{\\parbox{0.90\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      {\\fontsize{28}{34}\\selectfont\\bfseries\\color{accent}43\\% by 2030}\\\\[2pt]\n      {\\fontsize{22}{28}\\selectfont\\color{textlight}Emissions reduction}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.30\\linewidth}\\centering\n    \\fcolorbox{coolblue!50}{coolblue!20}{\\parbox{0.90\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      {\\fontsize{28}{34}\\selectfont\\bfseries\\color{coolblue}Net Zero $\\sim$2050}\\\\[2pt]\n      {\\fontsize{22}{28}\\selectfont\\color{textlight}CO$_2$ for 1.5\\textdegree C}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.30\\linewidth}\\centering\n    \\fcolorbox{tealgreen!50}{tealgreen!20}{\\parbox{0.90\\linewidth}{%\n      \\centering\\vspace{6pt}%\n      {\\fontsize{28}{34}\\selectfont\\bfseries\\color{tealgreen}$\\sim$500 GtCO$_2$}\\\\[2pt]\n      {\\fontsize{22}{28}\\selectfont\\color{textlight}Remaining budget}\\vspace{6pt}%\n    }}\n  \\end{minipage}\\\\[14pt]\n  {\\fontsize{26}{32}\\selectfont\\color{textdim}%\n    Source: IPCC, 2023.\\enspace AR6 Synthesis Report: Climate Change 2023.\\enspace Intergovernmental Panel on Climate Change.}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 445, "startLine": 1, "totalLines": 445}}

